pub fn all_digits(t: Text, from: u32, to: u32) -> bool {
    let mut i: u32 = from;
    while (i < to) {
        if !(is_digit(t.b[((i as usize)) as usize])) {
            return false;
        }
        i = (i + 1);
    }
    return true;
}

pub fn f64_overflow_bound() -> Big {
    return big_shl(big_sub(big_shl(big_u64(1), 54), big_u64(1)), 970);
}

pub fn digits_of(t: Text, from: u32, to: u32, dot: u32) -> Big {
    let mut d: Big = big_zero();
    let mut i: u32 = from;
    while (i < to) {
        if (i != dot) {
            d = big_mul_small(d, 10, ((t.b[((i as usize)) as usize] - 48) as u32));
        }
        i = (i + 1);
    }
    return d;
}

pub fn parsed(err: u8, q: Q128) -> QParse {
    return QParse { err: err, q: q };
}

pub fn parsed_opt(r: QOpt, err: u8) -> QParse {
    if !(r.ok) {
        return parsed(err, q_zero());
    }
    return parsed(OK, r.q);
}

pub fn q_parse(s: &[u8]) -> QParse {
    let t: Text = text_of(&s[(0) as usize..(s.len()) as usize]);
    if (t.n > 2048) {
        return parsed(TOO_LONG, q_zero());
    }
    if (((t.n >= 2) && (t.b[0] == 48)) && ((t.b[1] == 120) || (t.b[1] == 88))) {
        return parsed(HEX, q_zero());
    }
    let mut p: Parts = Parts { dot: t.n, mant: t.n, end: t.n };
    let mut i: u32 = 0;
    while (i < t.n) {
        if ((p.mant == t.n) && ((t.b[((i as usize)) as usize] == 101) || (t.b[((i as usize)) as usize] == 69))) {
            p.mant = i;
        }
        i = (i + 1);
    }
    i = 0;
    while (i < p.mant) {
        if ((p.dot == t.n) && (t.b[((i as usize)) as usize] == 46)) {
            p.dot = i;
        }
        i = (i + 1);
    }
    let mut ip_end: u32 = p.dot;
    if (p.dot > p.mant) {
        ip_end = p.mant;
    }
    let mut fp_from: u32 = p.mant;
    if (p.dot < p.mant) {
        fp_from = (p.dot + 1);
    }
    let mut exp_from: u32 = p.mant;
    if (p.mant < t.n) {
        exp_from = (p.mant + 1);
    }
    let mut exp_digits: u32 = exp_from;
    if ((exp_digits < t.n) && ((t.b[((exp_digits as usize)) as usize] == 43) || (t.b[((exp_digits as usize)) as usize] == 45))) {
        exp_digits = (exp_digits + 1);
    }
    let no_exp: bool = (p.mant == t.n);
    if (((((ip_end == 0) || !(all_digits(t, 0, ip_end))) || !(all_digits(t, fp_from, p.mant))) || (!(no_exp) && (exp_digits == t.n))) || !(all_digits(t, exp_digits, t.n))) {
        return parsed(MALFORMED, q_zero());
    }
    return parse_value(t, ip_end, fp_from, p.mant, exp_from, no_exp);
}

pub fn parse_value(t: Text, ip_end: u32, fp_from: u32, mant: u32, exp_from: u32, no_exp: bool) -> QParse {
    let mut first: u32 = 0;
    while ((first < mant) && ((t.b[((first as usize)) as usize] == 48) || (first == ip_end))) {
        first = (first + 1);
    }
    let mut x: Exp = Exp { value: 0, fits: true };
    if !(no_exp) {
        x = exp_of(t, exp_from, t.n);
    }
    if (first == mant) {
        return parsed(OK, q_zero());
    }
    let mut fp_len: i64 = 0;
    if (fp_from < mant) {
        fp_len = ((mant - fp_from) as i64);
    }
    let mut len: i64 = ((mant - first) as i64);
    if ((first < ip_end) && (ip_end < mant)) {
        len = (len - 1);
    }
    if ((!(x.fits) && (x.value > 0)) || (x.value > 1152921504606846976)) {
        return parsed(OVERFLOW_F64, q_zero());
    }
    if ((len * 4) > (BITS as i64)) {
        return parsed(TOO_LONG, q_zero());
    }
    let d: Big = digits_of(t, first, mant, ip_end);
    if (!(x.fits) || (x.value < -(1152921504606846976))) {
        return parsed(OK, q_zero());
    }
    let e10: i64 = (x.value - fp_len);
    if ((e10 + len) > 310) {
        return parsed(OVERFLOW_F64, q_zero());
    }
    if (e10 >= 0) {
        let n: Big = big_mul_pow10(d, (e10 as u32));
        if (big_cmp(n, f64_overflow_bound()) >= 0) {
            return parsed(OVERFLOW_F64, q_zero());
        }
        return parsed_opt(q_round(false, n, 0, false), OVERFLOW_F128);
    }
    return parse_fraction(d, len, e10);
}

pub fn parse_fraction(d: Big, len: i64, e10: i64) -> QParse {
    let k: i64 = (0 - e10);
    if ((e10 + len) > 308) {
        if ((((k * 10) / 3) + 1100) > (BITS as i64)) {
            return parsed(TOO_LONG, q_zero());
        }
        if (big_cmp(d, big_mul_pow10(f64_overflow_bound(), (k as u32))) >= 0) {
            return parsed(OVERFLOW_F64, q_zero());
        }
    }
    if ((e10 + len) < -(5000)) {
        return parsed(OK, q_zero());
    }
    if ((((k * 10) / 3) + 160) > (BITS as i64)) {
        return parsed(TOO_LONG, q_zero());
    }
    let den: Big = big_mul_pow10(big_u64(1), (k as u32));
    let mut s: i64 = (((big_bitlen(den) as i64) - (big_bitlen(d) as i64)) + 116);
    if (s < 0) {
        s = 0;
    }
    let q: Quot = big_div(big_shl(d, (s as u32)), den);
    return parsed_opt(q_round(false, q.q, (0 - s), q.rem), OVERFLOW_F128);
}

pub fn why(err: u8) -> &'static str {
    if (err == HEX) {
        return "hexadecimal float literal";
    }
    if (err == MALFORMED) {
        return "malformed float literal";
    }
    if (err == OVERFLOW_F64) {
        return "float literal overflows f64";
    }
    if (err == OVERFLOW_F128) {
        return "float literal overflows f128";
    }
    if (err == TOO_LONG) {
        return "float literal too long for t27b to fold";
    }
    return "";
}

pub fn lit(s: &[u8]) -> u64 {
    let r: QParse = q_parse(s);
    assert!((r.err == OK));
    let f: F64Bits = q_to_f64(r.q);
    assert!(f.ok);
    return f.bits;
}

pub fn lit_q(s: &[u8]) -> Q128 {
    let r: QParse = q_parse(s);
    assert!((r.err == OK));
    return r.q;
}

pub fn next(seed: u64) -> u64 {
    let mut x: u64 = seed;
    x = (x ^ (x << 13));
    x = (x ^ (x >> 7));
    x = (x ^ (x << 17));
    return x;
}

pub fn finite_of(x: u64) -> u64 {
    let mut bits: u64 = x;
    if ((x % 5) == 0) {
        bits = (x & 9232379236109516799);
    }
    if (((bits >> 52) & 2047) == 2047) {
        return 0;
    }
    return bits;
}

pub fn hw(op: u8, a: f64, b: f64) -> f64 {
    if (op == OP_ADD) {
        return (a + b);
    }
    if (op == OP_SUB) {
        return (a - b);
    }
    if (op == OP_MUL) {
        return (a * b);
    }
    return (a / b);
}

